r[1] = 4 - 2*sqrt(2);
O[1] = (r[1],r[1]);
r[2] = 4 + 2*sqrt(2);
O[2] = (r[2],r[2]);

draw(Circle(O[1],r[1]));
draw(arc(O[2],r[2],160,290));
draw(Circle((3,0),1));
